/* Offline interaction study. No API calls, remote commands or persistent writes. */
'use strict';
const $ = selector => document.querySelector(selector);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art = n => `assets/visual-${n}.svg`;
const clips = [
  {name:'Liquid architecture', theme:'Abstract', colour:'Teal', type:'3D animation', duration:'00:24', art:1, reviewed:true},
  {name:'Ultraviolet bloom', theme:'Organic', colour:'Purple', type:'Generative', duration:'00:18', art:2, reviewed:false},
  {name:'Ember current', theme:'Abstract', colour:'Orange', type:'Fluid', duration:'00:32', art:3, reviewed:false},
  {name:'Into the grid', theme:'Geometric', colour:'Blue', type:'3D animation', duration:'00:16', art:4, reviewed:true},
  {name:'Soft frequencies', theme:'Organic', colour:'Green', type:'Generative', duration:'00:28', art:5, reviewed:false},
  {name:'After hours', theme:'Abstract', colour:'Purple', type:'3D animation', duration:'00:20', art:6, reviewed:true},
  {name:'Golden hour', theme:'Geometric', colour:'Orange', type:'Generative', duration:'00:22', art:7, reviewed:false},
  {name:'Silver echo', theme:'Abstract', colour:'Silver', type:'3D animation', duration:'00:26', art:8, reviewed:false}
];
const state={screen:'prepare',inspector:'3D text',clip:0,liveClip:5,scenario:'ready',fullscreen:true,playing:true,previewPlaying:false,playlistLive:true,layout:'Single',skin:'Mirror',text:'VERSION1',selected:new Set(),libraryMode:'videos',query:'',theme:'All themes',reviewFilter:'All review states',transition:'liquid-chrome',effectQuery:'',effectCategory:'All categories',auto:false,saved:true,reviewIndex:1,undo:null,tagDeleted:false};
const navItems=[['prepare','Prepare'],['playlists','Playlists'],['library','Library'],['perform','Auto Perform']];
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const options=(values,selected)=>values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const field=(label,content)=>`<div class="field"><label>${label}</label>${content}</div>`;
const slider=(label,value,min,max,step=1)=>`<div class="field"><label>${label}<output>${value}</output></label><input aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
const select=(label,values,selected)=>`<select aria-label="${label}">${options(values,selected)}</select>`;
function notice(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.hidden=true,4500)}
function heading(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="row">${actions}</div></div>`}
function rail(){const offline=state.scenario==='offline',revoked=state.scenario==='revoked',locked=state.scenario==='locked';const disabled=offline||revoked||locked?'disabled':'';$('#live-rail').innerHTML=`<div class="live-status"><img class="live-thumb" src="${art(clips[state.liveClip].art)}" alt=""><div><div class="eyebrow live"><span class="dot"></span>${offline?'MAC NOT CONNECTED':state.playing?'PLAYING ON MAC':'MAC STOPPED'}</div><h3>${offline?'Last status unavailable':clips[state.liveClip].name}</h3><small>${state.playlistLive?'Playlist running':'Single look'} · Status only, not a live video feed</small><small class="connection-summary">${revoked?'Mac owns control':locked?'iPad owns control':'You own control'} · ${offline?'Engine offline':'Engine connected'} · ${state.fullscreen?'Fullscreen':'Windowed'}</small></div></div><div class="live-details"><p>${revoked?'Mac has control':locked?'iPad has control':'This device has control'}</p><p>${offline?'Engine offline':`Engine connected · ${state.fullscreen?'Fullscreen':'Windowed'}`}</p></div><div class="live-actions">${btn('Open output','open-output','quiet')}${btn(state.fullscreen?'Exit Mac fullscreen':'Mac fullscreen','fullscreen','quiet',disabled)}${btn('Next on Mac','next','quiet',disabled||(!state.playlistLive?'disabled':''))}${btn('■ Stop Mac','stop','stop',disabled)}${btn(state.screen==='playlists'?'Play playlist on Mac ↗':'Send to Mac ↗','send','primary',disabled)}</div>`}
function stage({branding=true,capture=false,review=false}={}){return `<div class="stage"><img src="${art(clips[review?state.reviewIndex:state.clip].art)}" alt="Illustrative ${clips[review?state.reviewIndex:state.clip].name} video still">${branding?`<div class="stage-text" id="stage-text">${esc(state.text)}</div>`:''}${capture?'<div class="capture-frame"></div>':''}<span class="stage-tag">${review?'INDEPENDENT REVIEW':'PRIVATE PREVIEW'} · ILLUSTRATIVE STILL</span>${!review&&!capture?btn('⛶','preview-fullscreen','stage-corner','aria-label="Preview fullscreen"'):''}${state.scenario==='proxy'?'<div class="preparing"><h2>Preparing your iPad preview</h2><p>Creating a compatible video. Your Mac show keeps playing.</p><progress aria-label="Preview preparation"></progress><small>Original video is unchanged</small></div>':''}</div>`}
function transport(review=false){return `<div class="transport">${btn(state.previewPlaying?'Ⅱ Pause':'▶ Play',review?'review-play':'preview-play','','aria-label="'+(review?'Play review video':'Play private preview')+'"')}<span class="time">00:08</span><input type="range" min="0" max="24" value="8" aria-label="${review?'Review':'Preview'} playhead"><span class="time">00:24</span>${btn('Muted','mute','quiet')}</div>`}
function clipCard(c,i,library=false){return `<article class="clip ${state.clip===i&&!library?'selected':''}">${library?`<label class="clip-select"><input type="checkbox" data-select="${i}" aria-label="Select ${c.name}" ${state.selected.has(i)?'checked':''}></label>`:''}<button class="clip-image" data-clip="${i}" aria-label="Prepare ${c.name}"><img src="${art(c.art)}" alt=""><span class="duration">${c.duration}</span></button><div class="clip-title"><strong>${c.name}</strong><small>${library?(c.reviewed?'✓ Reviewed':'○ Needs review'):c.theme+' · '+c.colour}</small>${library?`<div class="tag-list"><span class="tag">${c.theme}</span><span class="tag colour">${c.colour}</span><span class="tag type">${c.type}</span></div>`:''}</div>${library?`<div class="clip-actions"><button data-review="${i}">Review tags</button><button data-add="${i}" aria-label="Add ${c.name} to playlist">＋ Playlist</button></div>`:''}</article>`}
function shelf(){return `<section class="shelf"><div class="row spread"><div class="row" style="margin:0"><h2>Find your next look</h2><span class="pill">Library</span></div><button class="quiet" data-screen="library">Browse all videos →</button></div><div class="shelf-grid">${clips.slice(0,5).map((c,i)=>clipCard(c,i)).join('')}</div></section>`}
function inspector(){let body='';if(state.inspector==='3D text'){body=field('Text','<input id="text-input" aria-label="3D text" type="text" maxlength="80" value="'+esc(state.text)+'">')+field('Typeface',select('Typeface',['Modern sans','Bungee','Editorial serif'],'Modern sans'))+field('Finish',`<div class="swatches">${['Chrome','Mirror','Brushed','Gold','Rose gold','Obsidian','Pearl','Iridescent','Original'].map((v,i)=>`<button class="swatch ${['','', 'brushed','gold','rose','obsidian','pearl','iris','original'][i]} ${state.skin===v?'active':''}" data-skin="${v}" aria-pressed="${state.skin===v}"><span class="orb"></span>${v}</button>`).join('')}</div>`)+slider('Video reflection',1.2,0,2,.05)+field('Render quality',select('Render quality',['Balanced','High definition','Ultra'],'High definition'))+`<details><summary>Shape, light & motion</summary><div style="padding-top:18px">${slider('Bevel',.04,0,.1,.005)}${slider('Roughness',.12,.025,.8,.005)}${slider('Environment wrap',1,0,2,.1)}${slider('Brightness',1,.3,2,.1)}${slider('Depth',.2,0,1,.01)}${field('Rotation',select('Rotation',['Still','X axis','Y axis','Z axis'],'Y axis'))}<p>Position, size, rotation and sweep are grouped here in the implementation.</p></div></details>`}
else if(state.inspector==='Layout'){body=field('Composition',`<div class="segmented">${['Single','Dual','3×','4×','8×'].map(v=>`<button data-layout="${v}" aria-pressed="${state.layout===v}">${v}</button>`).join('')}</div>`)+field('Mirror pattern',select('Mirror pattern',Array.from({length:32},(_,i)=>'Pattern '+(i+1)),'Pattern 1'))+field('Playback',select('Playback',['Once','Loop','Bounce'],'Loop'))+`<p>Bounce currently plays as a forward loop on clean Mac output.</p>`+slider('Speed',1,.25,2,.25)+slider('Zoom',1,1,4,.1)+slider('Pan X',0,-1,1,.05)+slider('Pan Y',0,-1,1,.05)+btn('Save video layout','save-layout','full')+'<p>Stores layout and playback. FX and materials are not part of a saved layout.</p>'}
else if(state.inspector==='Colour'){body=field('Preset',select('Colour preset',['Original','Neon','Vintage','Acid','Night Vision','Inverted','Dreamy'],'Original'))+slider('Hue',0,0,360)+slider('Saturation',100,0,300)+slider('Contrast',100,50,200)+slider('Brightness',100,50,200)+slider('Blur',0,0,10,.1)+`<details><summary>Invert, sepia & trails</summary>${slider('Invert',0,0,100)}${slider('Sepia',0,0,100)}${slider('Trails',0,0,.96,.01)}</details>`}
else{body=field('Scene',select('VFX scene',['Liquid ripple','Image smear','Video ribbons','Mirror sculpture','Kaleidoscope tunnel','Prism fracture','3D logo / text'],'3D logo / text'))+slider('Intensity',1,0,2,.05)+slider('Feedback',.3,0,.96,.01)+btn('Pulse preview','pulse','full')+field('Object source',select('Object source',['Text','Version1 logo','Transparent artwork'],'Text'))+btn('Choose artwork…','artwork','full')+'<p>PNG / WebP up to 1 MB. Mirror sculpture keeps its own shape and reflection controls.</p><div class="divider"></div>'+btn('Preview audio settings','preview-audio','full')+'<p>Preview input belongs to this device. Configure the Mac input under Auto Perform.</p>'}
return `<aside class="panel inspector" aria-label="Preview inspector"><div class="panel-head"><h3>Edit this look</h3><span class="pill">Private</span></div><div class="tabs" aria-label="Inspector sections">${['Layout','Colour','VFX','3D text'].map(v=>`<button data-inspector="${v}" class="${state.inspector===v?'active':''}" aria-pressed="${state.inspector===v}">${v}</button>`).join('')}</div><div class="panel-body">${body}</div></aside>`}
function prepare(){return heading('YOUR WORKSPACE','Prepare a look','Explore freely. Only Send to Mac changes the show.',btn('＋ Add look to playlist','add-look','quiet'))+`<div class="prepare-grid"><div><section class="panel"><div class="stage-header"><div><strong>${clips[state.clip].name}</strong> <span class="pill" style="margin-left:10px">${state.layout} · Loop</span></div><span class="eyebrow">Preview</span></div>${stage()}${transport()}<div class="footnote"><span>Changes stay on this device until sent</span><span>Muted · 16:9</span></div></section>${shelf()}</div>${inspector()}</div>`}
function playlists(){return heading('SEQUENCE & AUDITION','After hours / opening','Build the sequence here. The Mac keeps playing its sent copy.',`<span class="pill ${state.saved?'':'amber'}">${state.saved?'Saved on Mac':'Unsaved changes'}</span>${btn('Save playlist','save-playlist','quiet')}`)+`<div class="playlist-layout"><div><div class="panel"><div class="stage-header"><strong>Sequence preview</strong><span class="pill">Private</span></div>${stage({branding:false})}${transport()}</div><section class="panel sequence"><div class="row spread" style="margin-bottom:18px"><h3>Playlist timeline <span class="muted">· 4 entries / 01:36</span></h3>${btn('＋ Add video','add-video','quiet')}</div><div class="ruler"><span>00:00</span><span>00:24</span><span>00:48</span><span>01:12</span><span>01:36</span></div><div class="timeline">${clips.slice(0,4).map((c,i)=>`${i?'<button class="transition" data-screen="transitions" aria-label="Edit incoming transition for '+c.name+'">◇</button>':''}<button data-entry="${i}" class="${state.clip===i?'active':''}"><img src="${art(c.art)}" alt=""><span>${String(i+1).padStart(2,'0')} · ${c.name}<br>24 seconds</span></button>`).join('')}</div><div class="cue">00:00 · 3D text / VERSION1</div><div class="mini-actions">${btn('↶ −1 sec','minus-sec','quiet')}${btn('+1 sec ↷','plus-sec','quiet')}${btn('＋ Current look','add-look','quiet')}${btn('Auto-generate','auto-generate','quiet')}</div></section></div><aside class="panel"><div class="panel-head"><h3>Selected entry</h3><span class="pill">${String(state.clip+1).padStart(2,'0')}</span></div><div class="panel-body">${field('Duration',select('Duration unit',['Seconds','Complete loops'],'Seconds')+'<input aria-label="Entry duration" type="number" value="24" min="1" style="margin-top:8px">')}${field('Incoming transition',btn(window.DESIGN_TRANSITIONS.find(e=>e.id===state.transition).name+' ↗','transitions','full'))}${slider('Transition duration',1.2,.15,10,.05)}${field('Pace',select('Transition pace',['Even','Build','Hit','Ease'],'Even'))}<div class="divider"></div><h3>Timed effects</h3><div class="list-row"><div>3D text<small>At 00:00 · Mirror</small></div>${btn('Edit','cue','quiet')}</div>${btn('＋ Add cue','cue','full quiet')}<div class="divider"></div><label class="row"><input type="checkbox" checked> Loop playlist</label><div class="mini-actions">${btn('← Move','move-entry','quiet')}${btn('Move →','move-entry','quiet')}</div><p style="margin-top:15px">Save updates the file. Play playlist on Mac sends a separate copy, including unsaved edits.</p></div></aside></div>`}
function library(){const filtered=clips.map((c,i)=>({c,i})).filter(({c})=>(state.theme==='All themes'||c.theme===state.theme)&&(state.reviewFilter==='All review states'||(state.reviewFilter==='Reviewed'?c.reviewed:!c.reviewed))&&[c.name,c.theme,c.colour,c.type].join(' ').toLowerCase().includes(state.query.toLowerCase()));return heading('YOUR SHARED COLLECTION','Library','Find the right visual. Keep its tags useful.',btn('Import from Instagram','import','quiet'))+`<div class="row spread" style="margin-bottom:20px"><div class="segmented">${btn('Videos · 8 demo clips','library-videos',state.libraryMode==='videos'?'active':'')}${btn('Tags & usage','library-tags',state.libraryMode==='tags'?'active':'')}</div>${btn('↶ Undo tag change','undo','quiet',state.undo?'':'disabled')}</div>`+(state.libraryMode==='tags'?vocabulary():`<div class="toolbar"><input class="search" id="library-search" aria-label="Search videos" placeholder="Search videos, themes, colours…" value="${esc(state.query)}"><select id="theme-filter" aria-label="Theme">${options(['All themes','Abstract','Organic','Geometric'],state.theme)}</select><select id="review-filter" aria-label="Review status">${options(['All review states','Needs review','Reviewed'],state.reviewFilter)}</select>${btn('More filters','more-filters','quiet')}</div>${state.selected.size?`<div class="bulk row spread wrap"><strong>${state.selected.size} selected${[...state.selected].some(i=>!filtered.some(f=>f.i===i))?' · includes hidden clips':''}</strong><div class="row wrap">${btn('Edit tags','bulk-tags')}${btn('Mark reviewed','mark-reviewed')}${btn('Clear','clear-selection','quiet')}</div></div>`:`<div class="row spread" style="margin-bottom:16px"><small>${filtered.length} videos · Illustrative collection</small><small>Arrange by: My order</small></div>`}<div class="library-grid">${filtered.length?filtered.map(({c,i})=>clipCard(c,i,true)).join(''):'<div class="empty"><h2>No matching videos</h2><p>Try a different word or clear the filters.</p>'+btn('Clear filters','clear-filters')+'</div>'}</div>`)}
function vocabulary(){const counts={};clips.forEach(c=>{counts[c.theme]=(counts[c.theme]||0)+1});return `<div class="two-columns"><section class="panel"><div class="panel-head"><h2>Classification vocabulary</h2><span class="pill">Shared on Mac</span></div><div class="panel-body"><p>Inspect assignments before renaming or removing a tag. Changes never delete media.</p><table class="table"><thead><tr><th>Theme</th><th>Videos</th><th>Manage</th></tr></thead><tbody>${Object.entries(counts).map(([name,count])=>`<tr><td>${name}</td><td>${count}</td><td><button data-vocabulary="${name}">Review →</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>One vocabulary, fewer mistakes</h2></div><div class="panel-body"><p>Categories stay separate: Themes describe the subject, Colours describe the palette, and Visual types describe the treatment.</p><div class="list-row"><div>Rename or merge<small>An existing destination tag is merged without duplicates.</small></div></div><div class="list-row"><div>Remove assignments<small>See the affected count before applying the change.</small></div></div><div class="list-row"><div>Undo last tag change<small>One shared undo step, available until the next edit or server restart.</small></div></div></div></section></div>`}
function transitions(){const chosen=window.DESIGN_TRANSITIONS.find(e=>e.id===state.transition);const filtered=window.DESIGN_TRANSITIONS.filter(e=>(state.effectCategory==='All categories'||e.category===state.effectCategory)&&e.name.toLowerCase().includes(state.effectQuery.toLowerCase()));return heading('PLAYLIST / INCOMING TRANSITION','Find the right change','Audition independently, then apply to the selected entry.',btn('← Back to playlist','back-playlists','quiet'))+`<div class="playlist-layout"><section><div class="toolbar"><input class="search" id="effect-search" aria-label="Search all 61 transitions" placeholder="Search all 61 transitions…" value="${esc(state.effectQuery)}"><select id="effect-category" aria-label="Transition category">${options(['All categories',...new Set(window.DESIGN_TRANSITIONS.map(e=>e.category))],state.effectCategory)}</select></div><p style="margin-bottom:16px">${filtered.length} effects · Illustrative tiles, not effect previews</p><div class="effect-grid">${filtered.map(e=>`<button class="effect-card ${state.transition===e.id?'active':''}" data-effect="${e.id}"><div class="effect-art"></div><strong>${e.name}</strong><small>${e.category}${e.safetyTags.length?' · '+e.safetyTags.join(', '):''}</small></button>`).join('')}</div></section><aside class="panel"><div class="panel-head"><h3>${chosen.name}</h3><span class="pill">Audition</span></div><div class="stage" style="aspect-ratio:4/3"><img src="${art(8)}" alt="Illustrative transition still"><span class="stage-tag">A → B · PRIVATE</span></div><div class="panel-body"><p style="margin-bottom:20px">${chosen.description}</p>${btn('▶ Replay audition','audition','full quiet')}<div class="divider"></div>${slider('Duration',1.2,.15,10,.05)}${field('Pace',select('Pace',['Even','Build','Hit','Ease'],'Even'))}${Object.entries(chosen.parameterDefinitions).map(([name,r])=>r.values?field(name,select(name,r.values,r.default)):r.type==='color'?field(name,`<input type="color" aria-label="${name}" value="${r.default}">`):slider(name,r.default,r.min,r.max,.01)).join('')}<label class="row" style="margin-bottom:18px"><input type="checkbox" checked> Reduce flashes</label>${btn('Use in selected entry','apply-transition','primary full')}<p style="margin-top:14px">WebGL2 unavailable? Use Cross Dissolve and show the fallback reason.</p></div></aside></div>`}
function perform(){return heading('LISTEN & RESPOND','Auto Perform','The Mac listens to your audio and chooses the next look.',btn('Mac audio setup','audio-setup','quiet'))+`<div class="two-columns"><section class="panel"><div class="panel-head"><div class="eyebrow live"><span class="dot"></span>${state.auto?'LISTENING ON MAC':'MAC INPUT READY · DEMO'}</div><span class="pill">USB audio input</span></div><div class="panel-body"><div class="row spread"><div><div class="metric">126<span><small> BPM</small></span></div><p>Steady pulse · High confidence</p></div><div class="pill">Bar 12 / 16</div></div><div class="meter" aria-label="Illustrative audio level meter">${Array.from({length:40},(_,i)=>`<i style="height:${12+(Math.sin(i*.8)+1)*18+(i%7)*4}px"></i>`).join('')}</div><div class="stats"><div><small>Musical section</small><h3>Build</h3></div><div><small>Next change</small><h3>In 4 bars</h3></div><div><small>Video pool</small><h3>8 videos</h3></div></div><div class="divider"></div><div class="row wrap">${btn('Hold video','hold','quiet','aria-pressed="false"')}${btn('Lock layout','lock-layout','quiet','aria-pressed="false"')}${btn('Next on beat','next-beat','quiet')}</div><div class="row" style="margin-top:10px">${btn('Tap tempo','tap','quiet')}${btn('Resync','resync','quiet')}</div></div></section><aside class="panel"><div class="panel-head"><h3>Performance settings</h3><span class="pill">Mac</span></div><div class="panel-body">${field('Profile',select('Auto Perform profile',['Balanced','Hypnotic','High Energy','Ambient'],'Hypnotic'))}${field('Change every',select('Change interval',['4 bars','8 bars','16 bars'],'16 bars'))}${field('Video pool',select('Video pool',['Entire library','Current playlist'],'Entire library'))}<p>Library search filters do not limit Entire library. Use curation to exclude clips.</p><div class="mini-actions">${btn('Curate videos','curate','quiet')}${btn('Text lists','text-lists','quiet')}</div><div class="divider"></div>${btn(state.auto?'Stop Auto Perform on Mac':'Start Auto Perform on Mac','auto',state.auto?'full':'primary full',state.scenario==='offline'||state.scenario==='revoked'?'disabled':'')}</div></aside></div><section class="panel" style="margin-top:24px"><div class="panel-head"><h3>Recent decisions</h3><small>Illustrative activity</small></div><div class="panel-body log"><div><b>23:42:08</b>Build detected · holding the current video until the next phrase</div><div><b>23:41:52</b>Layout changed · Dual / mirror pattern 5</div><div><b>23:41:36</b>After hours selected · Medium energy pool</div></div></section>`}
function capture(){return heading('RECORD & EXPORT','Capture your preview','Make a recording or a seamless social clip from this editor.')+`<div class="playlist-layout"><section class="panel"><div class="stage-header"><strong>Instagram clip</strong><span class="pill">This device’s preview</span></div>${stage({branding:false,capture:true})}${transport()}<div class="footnote"><span>Crop overlay · 4:5</span><span>Source untouched</span></div></section><aside class="panel"><div class="tabs">${btn('Instagram clip','capture-clip','active')}${btn('Full recording','capture-full','')}</div><div class="panel-body">${field('Format',select('Export format',['Feed · 4:5','Story · 9:16','Square · 1:1'],'Feed · 4:5'))}${field('Start time','<input aria-label="Source start time" type="text" value="00:08.00">')}${field('Finished duration','<input aria-label="Finished duration seconds" type="number" value="12" min=".1" max="600" step=".1">')}${field('Loop join',select('Loop transition',['Crossfade','Dissolve','Wipe','Slide','Pixelate','Circle open'],'Crossfade'))}${slider('Overlap seconds',1,.1,6,.1)}${btn('Capture 12-second clip','capture','primary full')}<p style="margin-top:15px">Silent MP4 · 1080 × 1350<br>Saved to the Mac’s clip folder.</p><div class="divider"></div><p>This captures your prepared preview, not the independently running Mac show.</p></div></aside></div>`}
function setup(){return heading('LOCAL STUDIO','Setup & connections','Configure once, then keep your attention on the show.')+`<div class="two-columns"><section class="panel"><div class="panel-head"><h2>Mac output</h2><span class="pill">Connected · Demo</span></div><div class="panel-body"><div class="list-row"><div>Dedicated output window<small>One output engine · native fullscreen control</small></div>${btn('Open output','open-output')}</div><div class="list-row"><div>Remote control<small>iPad and Mac must share the same local network</small></div><span class="pill">This device owns control</span></div><div class="list-row"><div>Mac audio input<small>First-use permission may require Mac setup</small></div>${btn('Configure','audio-setup')}</div><p style="margin-top:18px">On iPad, open http://&lt;Mac-local-IP&gt;:8008 in Safari. Keep the Mac awake during a show.</p></div></section><section class="panel"><div class="panel-head"><h2>Library & downloads</h2></div><div class="panel-body"><div class="list-row"><div>Video source folder<small>Mac server · downloads/</small></div>${btn('Change','source-folder')}</div><div class="list-row"><div>Instagram clip folder<small>Inherits source folder</small></div>${btn('Change','clip-folder')}</div><div class="list-row"><div>Instagram connection<small>Cookies valid · refresh after 7 days</small></div>${btn('Refresh cookies','cookies')}</div><label class="row" style="margin-top:20px"><input type="checkbox" checked> Reduce flashes in transitions</label></div></section></div><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Where your work lives</h2></div><div class="panel-body"><div class="stats" style="border:0;padding:0"><div><h3>Shared on Mac</h3><p>Videos, tags, playlists, saved layouts and manual library order.</p></div><div><h3>In this browser</h3><p>Text lists, performance curation and some audio/display preferences.</p></div><div><h3>Current session</h3><p>Control ownership, command results and the last tag undo.</p></div></div></div></section>`}
function render(){state.screen=location.hash.slice(1)||state.screen;if(!['prepare','playlists','library','perform','transitions','capture','setup'].includes(state.screen))state.screen='prepare';$('#nav').innerHTML=navItems.map(([id,label])=>`<button data-screen="${id}" class="${state.screen===id?'active':''}" ${state.screen===id?'aria-current="page"':''}>${label}</button>`).join('');rail();let banner='';if(state.scenario==='offline')banner='<div class="banner"><div><strong>Mac connection lost</strong><p>Live controls are unavailable. Keep preparing; playback status cannot be confirmed.</p></div>'+btn('Reconnect','reconnect')+'</div>';if(state.scenario==='revoked')banner='<div class="banner"><div><strong>Control returned to Mac</strong><p>Your private preview is still available. Take control explicitly to send again.</p></div>'+btn('Take remote control','reclaim')+'</div>';$('#workspace').innerHTML=banner+({prepare,playlists,library,transitions,perform,capture,setup}[state.screen])();$('.app-header').inert=state.scenario==='locked';$('#workspace').inert=state.scenario==='locked';$('#workspace').classList.toggle('locked',state.scenario==='locked');if(['offline','revoked','locked'].includes(state.scenario))document.querySelectorAll('[data-action=auto],[data-action=hold],[data-action=lock-layout],[data-action=next-beat],[data-action=tap],[data-action=resync]').forEach(button=>button.disabled=true);if(state.scenario==='locked')lockDialog();}
function navigate(screen){if(location.hash==='#'+screen){state.screen=screen;render()}else location.hash=screen;window.scrollTo(0,0)}
function modal(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<div class="dialog-top"><div><div class="eyebrow" style="margin-bottom:6px">${state.scenario==='locked'?'CONTROL HANDOVER':'PRIVATE WORKSPACE'}</div><h2 id="dialog-title">${title}</h2></div>${state.scenario==='locked'?'':btn('✕','close-dialog','quiet','aria-label="Close dialog"')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function lockDialog(){modal('Being remote controlled by iPad',`<div class="lock-card"><div class="eyebrow live">OUTPUT KEEPS PLAYING</div><h2>The iPad has the controls.</h2><p>Your Mac editor is kept exactly where you left it. Return control to continue here.</p><div class="row wrap">${btn('Return control to Mac','reclaim','primary')}${btn('Open output screen','open-output','quiet')}</div></div>`)}
function review(index){state.reviewIndex=index;state.reviewDraft=JSON.parse(JSON.stringify(clips[index]));state.reviewDirty=false;drawReview()}
function drawReview(){const c=state.reviewDraft;modal(`Review tags · ${clips[state.reviewIndex].name}`,`${state.scenario==='conflict'?'<div class="review-conflict"><p><strong>This catalogue changed on another device.</strong> Your draft is preserved. Reload saved tags, then reconcile before saving.</p>'+btn('Reload saved tags','reload-tags','quiet')+'</div>':''}<div class="two-columns"><div class="panel review-player">${stage({branding:false,review:true})}${transport(true)}<div class="footnote">Review playback never changes your prepared look or Mac output.</div></div><div>${[['Theme','theme'],['Colour','colour'],['Visual type','type']].map(([label,key])=>`<div class="field"><label>${label}</label><div class="review-tags">${c[key]?`<button data-remove-tag="${key}" aria-label="Remove ${esc(c[key])} ${label} tag">${esc(c[key])} ×</button>`:''}</div><input type="text" data-tag-input="${key}" aria-label="Add ${label}" placeholder="Add or choose a ${label.toLowerCase()}…" list="${key}-choices"><datalist id="${key}-choices">${[...new Set(clips.map(c=>c[key]))].map(v=>`<option value="${v}">`).join('')}</datalist></div>`).join('')}${field('Notes',`<textarea id="review-notes" aria-label="Classification notes" maxlength="300" placeholder="Useful context for the next show…">${esc(c.notes||'')}</textarea>`)}<label class="row"><input type="checkbox" id="reviewed" ${c.reviewed?'checked':''}> Classification reviewed</label><p style="margin-top:14px">Changes are shared with every device.</p></div></div>`,`<small>Video ${state.reviewIndex+1} of ${clips.length} · Demo review queue</small><div class="row">${btn('Cancel','close-dialog','quiet')}${btn('Save tags','save-tags','quiet')}${btn('Save & next →','save-next','primary')}</div>`)}
function saveReview(next){if(state.scenario==='conflict'){notice('Conflict: draft kept. Reload saved tags before saving.');return}state.undo=JSON.stringify(clips);Object.assign(clips[state.reviewIndex],state.reviewDraft);if(next){review((state.reviewIndex+1)%clips.length)}else $('#dialog').close();render();notice('Demo: tags saved in this prototype session. Mac output unchanged.')}
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.dataset.screen){navigate(el.dataset.screen);return}if(el.dataset.inspector){state.inspector=el.dataset.inspector;render();return}if(el.dataset.skin){state.skin=el.dataset.skin;render();notice(`${state.skin} selected. Material tiles are illustrative; this prototype does not render 3D.`);return}if(el.dataset.layout){state.layout=el.dataset.layout;render();notice('Layout selection updated. Composition rendering is part of implementation.');return}if(el.dataset.clip!==undefined){state.clip=+el.dataset.clip;navigate('prepare');return}if(el.dataset.review!==undefined){review(+el.dataset.review);return}if(el.dataset.add!==undefined){notice(`${clips[+el.dataset.add].name} would be added through the playlist picker.`);return}if(el.dataset.entry!==undefined){state.clip=+el.dataset.entry;render();return}if(el.dataset.effect){state.transition=el.dataset.effect;render();return}if(el.dataset.removeTag){state.reviewDraft[el.dataset.removeTag]='';state.reviewDirty=true;drawReview();return}if(el.dataset.vocabulary){const tag=el.dataset.vocabulary,count=clips.filter(c=>c.theme===tag).length;state.vocabularyTag=tag;modal(`Theme: ${tag}`,`<p>${count} videos use this theme. Review their assignments before applying a global change.</p><div class="shelf-grid" style="margin:18px 0">${clips.map((c,i)=>c.theme===tag?clipCard(c,i):'').join('')}</div>${field('Rename / merge into','<input id="rename-tag" aria-label="New theme name" type="text" value="'+tag+'" maxlength="40">')}<p>Using an existing theme name merges its assignments.</p>`,`${btn('Remove from '+count+' videos','delete-tag','danger')}${btn('Rename on '+count+' videos','rename-tag','primary')}`);return}const action=el.dataset.action;if(!action)return;
switch(action){
case 'send': state.liveClip=state.clip;state.playing=true;state.playlistLive=state.screen==='playlists';rail();notice('Demo: command confirmed. The Mac would now play this '+(state.playlistLive?'playlist copy.':'look.'));break;
case 'stop':state.playing=false;state.auto=false;state.playlistLive=false;rail();notice('Demo: Mac stopped. The last frame stays visible; this is not a blackout.');break;
case 'next':state.liveClip=(state.liveClip+1)%clips.length;rail();notice('Demo: Mac advanced. Private preview unchanged.');break;
case 'fullscreen':state.fullscreen=!state.fullscreen;rail();notice('Demo: dedicated Mac output '+(state.fullscreen?'entered fullscreen.':'returned to windowed mode.'));break;
case 'open-output':notice('Demo: open or focus the dedicated Mac output, preserving its fullscreen state.');break;
case 'preview-fullscreen':modal('Preview fullscreen',stage()+`<p style="margin-top:15px">This expands only your private preview. Mac fullscreen is a separate action in the pinned bar.</p>`);break;
case 'preview-play':case 'review-play':state.previewPlaying=!state.previewPlaying;el.textContent=state.previewPlaying?'Ⅱ Pause':'▶ Play';notice('Playback control demonstration. Artwork is a still; no video is loaded in this prototype.');break;
case 'mute':el.textContent=el.textContent==='Muted'?'Unmuted':'Muted';break;
case 'reconnect':case 'reclaim':state.scenario='ready';$('#scenario').value='ready';$('#dialog').close();render();notice('Demo: this device has control.');break;
case 'transitions':navigate('transitions');break;
case 'back-playlists':navigate('playlists');break;
case 'apply-transition':state.saved=false;navigate('playlists');notice('Transition assigned to the selected entry. Save the playlist to keep it.');break;
case 'save-playlist':state.saved=true;render();notice('Demo: playlist saved. Already sent Mac copy unchanged.');break;
case 'library-tags':state.libraryMode='tags';render();break;
case 'library-videos':state.libraryMode='videos';render();break;
case 'clear-selection':state.selected.clear();render();break;
case 'mark-reviewed':state.undo=JSON.stringify(clips);state.selected.forEach(i=>clips[i].reviewed=true);render();notice('Selected demo clips marked reviewed. Undo is available.');break;
case 'clear-filters':state.query='';state.theme='All themes';state.reviewFilter='All review states';render();break;
case 'undo':if(state.undo){const old=JSON.parse(state.undo);clips.splice(0,clips.length,...old);state.undo=null;render();notice('Last demo tag change undone.')}break;
case 'rename-tag':case 'delete-tag':{const name=$('#rename-tag').value.trim();if(action==='rename-tag'&&!name){notice('Enter a theme name.');break}state.undo=JSON.stringify(clips);clips.forEach(c=>{if(c.theme===state.vocabularyTag)c.theme=action==='delete-tag'?'Untagged':name});$('#dialog').close();render();notice('Demo assignments updated. Undo is available.');break}
case 'close-dialog':if(state.reviewDirty){state.reviewDirty=false;notice('Unsaved review changes discarded.')}$('#dialog').close();break;
case 'save-tags':saveReview(false);break;
case 'save-next':saveReview(true);break;
case 'reload-tags':state.scenario='ready';$('#scenario').value='ready';review(state.reviewIndex);break;
case 'auto':state.auto=!state.auto;state.playing=state.auto||state.playing;state.playlistLive=false;render();notice('Demo: Auto Perform '+(state.auto?'started on Mac.':'stopped; the current look remains.'));break;
case 'hold':case 'lock-layout':{const active=el.getAttribute('aria-pressed')!=='true';el.setAttribute('aria-pressed',active);el.classList.toggle('active',active);break}
case 'capture':modal('Capture your preview','<p>This flow captures the editor, converts it to a silent H.264 MP4 and saves it to the Mac’s configured clip folder.</p><div class="list-row"><strong>1. Capturing</strong><small>Includes overlap footage</small></div><div class="list-row"><strong>2. Converting</strong><small>Keep conversion status visible</small></div><div class="list-row"><strong>3. Ready to download</strong><small>12 seconds · 1080 × 1350</small></div>','<small>Design demonstration. No media file is created.</small>'+btn('Done','close-dialog','primary'));break;
case 'capture-full':modal('Record this editor','<p>Records this device’s prepared composition at 1920 × 1080 / 30 fps. It does not record the independent Mac show.</p><div class="list-row"><div>Include source audio<small>Only when unmuted and capture support permits it</small></div></div><p>States: Recording → Waiting for loop boundary, if needed → Converting → Download MP4.</p>','<small>Recording is simulated in this concept.</small>'+btn('Done','close-dialog','primary'));break;
case 'audio-setup':modal('Set up audio on the Mac','<p>Select the Mac microphone, USB interface or virtual input. First-time browser and macOS permissions may need a local click.</p><div class="field" style="margin-top:20px"><label>Mac input</label>'+select('Mac audio input',['USB audio input','Built-in microphone'],'USB audio input')+'</div><p>Closing setup keeps the resident engine alive. The input is analysed, not played through the speakers.</p>',btn('Done','close-dialog','primary'));break;
case 'import':modal('Import from Instagram',field('Reel or post URL','<input class="full" aria-label="Instagram URL" placeholder="https://www.instagram.com/reel/…" type="url">')+'<p>Downloads run on the Mac. Completed videos appear in your shared library, initially untagged.</p>',`<small>Cookies valid · demo</small>${btn('Download video','demo-download','primary')}`);break;
case 'demo-download':notice('Design demonstration: download progress, authentication errors and retry would appear here.');break;
case 'more-filters':modal('Library filters',field('Colour',select('Colour',['All colours','Teal','Purple','Blue','Orange','Green','Silver'],'All colours'))+field('Visual type',select('Visual type',['All types','3D animation','Generative','Fluid'],'All types'))+field('Arrange by',select('Arrange by',['My order','Theme','Colour','Visual type','Name','Newest first'],'My order'))+'<p>These are layout examples. The prototype filters by search, theme and review status on the main Library screen.</p>',btn('Done','close-dialog','primary'));break;
case 'text-lists':modal('Text lists',field('Selected list',select('Text list',['Version1 regulars','Event night'],'Version1 regulars'))+'<div class="list-row"><span>VERSION1</span><span class="pill">Event name</span></div><div class="list-row"><span>@tonyt.dj</span><span class="pill">Instagram</span></div><div class="list-row"><span>version1djs.com</span><span class="pill">Website</span></div><p style="margin-top:16px">Lists live in this browser. Enabled entries are copied to the Mac when Auto Perform starts.</p>',btn('Done','close-dialog','primary'));break;
case 'curate':modal('Curate the performance pool','<p>Performance energy and exclusions are browser-local. They are separate from shared classification tags.</p>'+clips.slice(0,4).map(c=>`<div class="list-row"><label class="row"><input type="checkbox" checked>${c.name}</label>${select(c.name+' energy',['Calm','Medium','Peak'],'Medium')}</div>`).join(''),btn('Done','close-dialog','primary'));break;
case 'cue':modal('Timed effect cue',field('At time in entry','<input aria-label="Cue time" type="number" value="0" min="0">')+field('Effect',select('Cue effect',['3D text','3D logo','VFX scene','Off'],'3D text'))+field('Text','<input type="text" aria-label="Cue text" value="VERSION1">')+field('Material',select('Cue material',['Chrome','Mirror','Gold','Pearl'],'Mirror'))+'<p>A cue is inside this entry. Its timing is independent of the incoming transition.</p>',btn('Done','close-dialog','primary'));break;
case 'bulk-tags':modal('Edit tags on '+state.selected.size+' selected videos',field('Category',select('Bulk category',['Theme','Colour','Visual type'],'Theme'))+field('Operation',select('Bulk operation',['Add tag','Remove tag'],'Add tag'))+field('Tag','<input aria-label="Bulk tag" type="text" placeholder="Choose or enter a tag">')+'<p>This detail view illustrates the form. Selection and Mark reviewed / Undo are working demo interactions; bulk tag writes are not connected.</p>',btn('Done','close-dialog','primary'));break;
case 'add-video':navigate('library');break;
case 'add-look':modal('Add current look to playlist',field('Playlist',select('Destination playlist',['After hours / opening','New playlist…'],'After hours / opening'))+field('Duration in seconds','<input aria-label="Clip duration" type="number" value="24">')+'<p>Includes the current composition and active effects as a cue. Quick Add saves immediately; timeline edits use Save playlist.</p>',btn('Add look','demo-add-look','primary'));break;
case 'demo-add-look':$('#dialog').close();notice('Demo: look added through Quick Add. The running Mac playlist is unchanged.');break;
case 'save-layout':modal('Save video layout',field('Layout name','<input aria-label="Layout name" value="Single / loop / 1×">')+'<p>Saves layout, mirror pattern, playback, speed, zoom and pan for this video. To keep FX and material settings, add the look to a playlist cue.</p>',btn('Done','close-dialog','primary'));break;
case 'auto-generate':modal('Generate a playlist',field('Target minutes','<input aria-label="Target minutes" type="number" value="15">')+'<p>Uses the current visible library results or visible checked videos. Creates an editable sequence; it does not start audio-reactive Auto Perform.</p>',btn('Done','close-dialog','primary'));break;
default:notice('Design detail: '+({'audition':'isolated A/B transition replay; effect rendering is not connected.','artwork':'choose a transparent PNG or WebP up to 1 MB.','preview-audio':'select input and sensitivity for this device’s private preview.','cookies':'refresh Brave cookies on the Mac; show progress and authentication errors.','source-folder':'browse the Mac filesystem; changing the source folder does not move files.','clip-folder':'choose the Mac folder for Instagram clip exports.','move-entry':'move the selected entry one position without drag-and-drop.','next-beat':'request the next Mac look on a beat.','tap':'send a tap-tempo event to the Mac engine.','resync':'reset the Mac beat alignment.','pulse':'pulse only the private VFX preview.'}[action]||'this secondary control is represented for layout review.'));}}
);
document.addEventListener('input',event=>{const el=event.target;if(el.type==='range'){const output=el.closest('.field')?.querySelector('output');if(output)output.textContent=el.value}if(el.id==='text-input'){state.text=el.value;$('#stage-text').textContent=state.text}if(el.id==='review-notes'){state.reviewDraft.notes=el.value;state.reviewDirty=true}if(['library-search','effect-search'].includes(el.id)){const pos=el.selectionStart;state[el.id==='library-search'?'query':'effectQuery']=el.value;render();const next=$('#'+el.id);next.focus();next.setSelectionRange(pos,pos)}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.select!==undefined){const i=+el.dataset.select;el.checked?state.selected.add(i):state.selected.delete(i);render()}if(el.id==='theme-filter'){state.theme=el.value;render()}if(el.id==='review-filter'){state.reviewFilter=el.value;render()}if(el.id==='effect-category'){state.effectCategory=el.value;render()}if(el.id==='reviewed'){state.reviewDraft.reviewed=el.checked;state.reviewDirty=true}if(el.dataset.tagInput&&el.value.trim()){state.reviewDraft[el.dataset.tagInput]=el.value.trim().slice(0,40);state.reviewDirty=true;const chips=el.closest('.field').querySelector('.review-tags');chips.innerHTML='<button data-remove-tag="'+el.dataset.tagInput+'" aria-label="Remove '+esc(state.reviewDraft[el.dataset.tagInput])+'">'+esc(state.reviewDraft[el.dataset.tagInput])+' ×</button>';el.value=''}});
$('#scenario').addEventListener('change',event=>{state.scenario=event.target.value;$('#dialog').close();render();if(state.scenario==='conflict')review(1)});
$('#fidelity').addEventListener('click',()=>{const active=document.body.classList.toggle('wireframe');$('#fidelity').setAttribute('aria-pressed',active);$('#fidelity').textContent=active?'Detailed mockup':'Wireframe'});
$('#dialog').addEventListener('cancel',event=>{if(state.scenario==='locked')event.preventDefault()});
window.addEventListener('hashchange',render);
const params=new URLSearchParams(location.search);if(params.get('wireframe')==='1'){$('body').classList.add('wireframe');$('#fidelity').textContent='Detailed mockup';$('#fidelity').setAttribute('aria-pressed','true')}if(params.has('state')){state.scenario=params.get('state');$('#scenario').value=state.scenario}render();if(state.scenario==='conflict')review(1);
